let selectedNode='system/services/payments';
const nodeMap=new Map(NODES.map(n=>[n.node,n]));
const nodeName=n=>n==='.'?'example_product':n.split('/').pop();
const nodeTarget=link=>{if(nodeMap.has(link))return link;const clean=link.split('#')[0];return clean.includes('.md')?clean.split('/').slice(0,-1).join('/'):clean;};
const downstream=n=>NODES.filter(x=>x.derives_from.some(l=>nodeTarget(l)===n.node));
const fileState=(node,document)=>SCENARIOS[stage].docs.find(d=>d.document===`${node}/${document}.md`)?.state;
function nodeLink(n){return `<button class="relation" data-inspect="${escape(n.node)}"><span class="node-symbol">◇</span><span><strong>${escape(nodeName(n.node))}</strong><small>${escape(n.node)}</small></span><span class="type-tag">${escape(n.type)}</span><span>↗</span></button>`;}
function nodeHeader(n,compact=false){return `<div class="node-identity ${compact?'compact':''}"><div><div class="eyebrow">${compact?'DOCUMENT BELONGS TO':'SPEC NODE'} <span class="type-tag">${escape(n.type)}</span></div><h1>${escape(nodeName(n.node))}</h1><div class="node-path">${escape(n.node)}</div></div><div class="node-actions">${compact?`<button data-inspect="${escape(n.node)}">Node overview ↗</button>`:'<button data-node-context>Copy context</button><button data-node-review>Review with Claude</button>'}</div></div>`;}
function inspectNode(key){const n=nodeMap.get(key);if(!n)return;selectedNode=key;$('state-frame').hidden=true;$('editor').hidden=true;$('node-overview').hidden=false;$('state-tab').classList.remove('active');$('file-tab').classList.remove('active');$('node-tab').classList.add('active');$('node-tab').textContent='◇ '+nodeName(key);$('breadcrumbs').textContent='Spec Tree › '+key.replaceAll('/',' › ');const down=downstream(n);const up=n.derives_from.map(nodeTarget).map(k=>nodeMap.get(k)).filter(Boolean);const changed=SCENARIOS[stage].docs.filter(d=>d.document.startsWith(key+'/'));
$('node-overview').innerHTML=nodeHeader(n)+`<div class="node-body">${changed.length?`<div class="change-notice"><span>◉</span><div><strong>Part of refund-window</strong><span>${changed.length} documents tracked in this change</span></div><button data-open-change>View change →</button></div>`:''}<section class="node-documents"><h2>Documents <span>${n.documents.length}</span></h2><div class="document-grid">${n.documents.map(d=>{const st=fileState(key,d);return `<button class="document-card" data-node-doc="${escape(key)}|${escape(d)}"><span class="doc-symbol">Ⓜ</span><span><strong>${escape(d)}.md</strong><small>${escape({api:'Public contracts and endpoints',logic:'Rules and service behavior',storage:'Data model and persistence',events:'Published and consumed events',compliance:'Compliance requirements',rules:'Product rules and cases','user-story':'Problem and intended outcome'}[d]||'Specification document')}</small></span>${st?`<span class="doc-state ${st}">${escape(st)}</span>`:'<span class="card-arrow">↗</span>'}</button>`;}).join('')}</div></section><div class="relationships"><section><h2>Upstream <span>${up.length}</span></h2><p class="section-caption">This node derives from</p>${up.length?up.map(nodeLink).join(''):'<p class="empty-note">No upstream links.</p>'}</section><section><h2>Downstream <span>${down.length}</span></h2><p class="section-caption">Nodes that depend on this one</p>${down.length?down.map(nodeLink).join(''):'<p class="empty-note">No downstream links.</p>'}</section></div><section class="code-section"><h2>Code paths <span>${n.code.length}</span></h2>${n.code.length?n.code.map(c=>`<button class="code-path" data-code-path="${escape(c)}">⌘ <code>${escape(c)}</code><span>↗</span></button>`).join(''):'<p class="empty-note">This node describes the product and has no code paths.</p>'}</section><section class="context-section"><div><h2>Context</h2><p>Instructions, ancestors, upstream documents, and change details for this node.</p></div><button data-node-context>View context →</button></section></div>`;
document.querySelectorAll('[data-tree-node]').forEach(b=>{b.classList.toggle('node-selected',b.dataset.treeNode===key);b.setAttribute('aria-current',String(b.dataset.treeNode===key));});
const selected=document.querySelector('[data-tree-node].node-selected'); if(selected){let parent=selected.parentElement.parentElement.parentElement;while(parent){if(parent.tagName==='DETAILS')parent.open=true;parent=parent.parentElement;}selected.scrollIntoView({block:'nearest'});}
$('output').textContent=`Selected ${key}\n${n.documents.length} documents · ${up.length} upstream · ${down.length} downstream · ${n.code.length} code paths`;}
const oldOpenState=openState;openState=function(){oldOpenState();$('node-overview').hidden=true;$('node-tab').classList.remove('active');};
const oldShowEditor=showEditor;showEditor=function(...args){oldShowEditor(...args);$('node-overview').hidden=true;$('node-context').hidden=true;$('node-tab').classList.remove('active');};
doc=function(key){const parts=key.split('/'),d=parts.pop().replace('.md',''),node=parts.join('/')||'.';const n=nodeMap.get(node);if(!n){showEditor('docs/'+key,'Sample document not included in this preview.');return;}selectedNode=node;showEditor('docs/'+key,n.contents[d]||'# '+d);$('node-context').hidden=false;$('node-context').innerHTML=nodeHeader(n,true);$('node-tab').textContent='◇ '+nodeName(node);document.querySelectorAll('[data-tree-node]').forEach(b=>b.classList.toggle('node-selected',b.dataset.treeNode===node));};
function contextText(){const n=nodeMap.get(selectedNode);return `${n.node}\n\n# Documents\n${n.documents.map(d=>`docs/${n.node}/${d}.md`).join('\n')}\n\n# Upstream\n${n.derives_from.join('\n')||'none'}\n\n# Code\n${n.code.join('\n')||'none'}\n\n# Change\n.uspec/changes/refund-window/change.md`;}
function renderTree(){const children=parent=>NODES.filter(n=>n.node!=='.'&&(n.node.includes('/')?n.node.slice(0,n.node.lastIndexOf('/')):'.')===parent);function branch(n){const cs=children(n.node);const expanded=['.','system','system/services','product','product/support'].includes(n.node);return `<details class="unified-branch" ${expanded?'open':''}><summary><button data-tree-node="${escape(n.node)}" title="Open ${escape(n.node)} overview">◇ ${escape(nodeName(n.node))}<small>${escape(n.type)}</small></button></summary><div>${cs.map(branch).join('')}${n.documents.map(d=>`<button class="tree-document" data-node-doc="${escape(n.node)}|${escape(d)}">Ⓜ ${escape(d)}.md</button>`).join('')}</div></details>`;}document.querySelector('#spec-section>.tree').innerHTML=branch(nodeMap.get('.'));}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-inspect],[data-tree-node],[data-node-doc],[data-open-change],[data-node-context],[data-code-path],[data-node-review]');if(!el)return;if(el.dataset.inspect)inspectNode(el.dataset.inspect);else if(el.dataset.treeNode){e.preventDefault();inspectNode(el.dataset.treeNode);}else if(el.dataset.nodeDoc){const [n,d]=el.dataset.nodeDoc.split('|');doc(`${n==='.'?'':n+'/'}${d}.md`);}else if(el.hasAttribute('data-open-change'))openState();else if(el.hasAttribute('data-node-context')){if(el.textContent==='Copy context'){try{await navigator.clipboard.writeText(contextText());toast('Node context copied.');}catch{showEditor('Context',contextText());}}else showEditor('Context',contextText());}else if(el.dataset.codePath)showEditor(el.dataset.codePath,'Code path linked to this spec node.\n\nThis preview shows specification data only.');else modal('Review with Claude',`<p>The extension would start a review of <strong>${escape(selectedNode)}</strong> using its documents and upstream context.</p><p>Agents are simulated in this preview.</p>`);});
$('node-tab').onclick=()=>inspectNode(selectedNode);$('state-tab').onclick=$('change-title').onclick=$('show-state').onclick=openState;
$('info').onclick=()=>modal('Unified node navigation','<p>Select a node in the Spec Tree to open its overview in the main area. Its documents, upstream and downstream links, code paths, and context now live together.</p><p>Open a document and the node identity stays above it, with a link back to the overview. The separate Node sidebar view is removed.</p><p>This is a layout proposal; the extension itself is unchanged.</p>');
renderTree();inspectNode(selectedNode);
